import { useSettingStore, useAutoAccountingStore } from 'src/store/main';
import {
  auto_accounting_setting,
  auto_accounting_types_setting,
} from 'src/constants';
import { Acl, Cache as Acl_Cache } from 'src/core/acls/index';
import { objLen } from 'src/utils/general';

/**
 * Cache all necessary data after user login
 * This function is called once after successful authentication
 */
export async function cacheDataAfterLogin(): Promise<void> {
  try {
    // Skip ACL fetch if already loaded in Step 2 of PrepareDashboard
    const cachedAcls = Acl_Cache.get();
    if (!cachedAcls || objLen(cachedAcls) === 0) {
      await Acl.fetch();
    }

    // Load auto-accounting data
    await loadAutoAccountingData();
  } catch (err) {
    logError('Failed to cache data after login:', err);
  }
}

/**
 * Load auto-accounting data based on user settings
 */
export async function loadAutoAccountingData(): Promise<void> {
  try {
    const settings_store = useSettingStore();
    // Skip if settings were already fetched in PrepareDashboard Step 3
    if (objLen(settings_store.user_settings) === 0) {
      await settings_store.startSettingsFetch();
    }

    if (!settings_store.user_settings[auto_accounting_setting]) return;

    const template_name = settings_store.user_settings[auto_accounting_types_setting];

    const autoAccountingStore = useAutoAccountingStore();
    if (template_name === 'm3') {
      await autoAccountingStore.fetchM3AccountsPromise();
    } else {
      await autoAccountingStore.fetchLnAccountsPromise();
    }
  } catch (err) {
    logError('Failed to load auto-accounting accounts:', err);
  }
}
